const site = { id: 1, name: '二厂3楼', owner: '小张' };
const resp = (msg.payload && msg.payload.data) ? msg.payload.data : (msg.payload || {});
const teamsWebhook = resp.teamsWebhook;
const intervals = resp.intervals || [];
const alerted = flow.get('alerted') || {};
const recoveredSent = flow.get('recoveredSent') || {};
const first = !flow.get('inited');
const out = [];

for (const iv of intervals) {
    if (!iv.start) continue;
    const seen = alerted[iv.start];
    if (first) {
        // 首次启动：只登记历史，不通知，防重启轰炸
        alerted[iv.start] = true;
        if (!iv.ongoing) recoveredSent[iv.start] = true;
        continue;
    }
    if (!seen) {
        // 断线开始：只报一次；离线不足 60 秒先不报（防抖，下一轮再判）
        if (iv.ongoing && iv.durationSec < 60) continue;
        alerted[iv.start] = true;
        out.push({ type: 'offline', iv: iv });
    } else if (!iv.ongoing && !recoveredSent[iv.start]) {
        // 恢复：之前报过断线且已结束，补一条恢复通知
        recoveredSent[iv.start] = true;
        out.push({ type: 'recovered', iv: iv });
    }
}
flow.set('inited', true);
flow.set('alerted', alerted);
flow.set('recoveredSent', recoveredSent);
msg.site = site;
msg.teamsWebhook = teamsWebhook;
msg.payload = out;
return msg;

const iv = msg.payload.iv;
const type = msg.payload.type;
const title = type === 'offline' ? '【EdgeLink 断线告警】' : '【EdgeLink 恢复通知】';
const lines = [
    `${msg.site.name} 于 ${iv.start} 断线。`,
    iv.ongoing
        ? `当前仍未恢复（已持续 ${Math.floor(iv.durationSec / 60)} 分钟）`
        : `已于 ${iv.end} 恢复（离线 ${Math.floor(iv.durationSec / 60)} 分钟）`,
    `疑似重启：${iv.restarted ? '是' : '否'}`,
    `负责人：${msg.site.owner}`
];
msg.payload = {
    type: 'message',
    attachments: [{
        contentType: 'application/vnd.microsoft.card.adaptive',
        content: {
            '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
            type: 'AdaptiveCard',
            version: '1.4',
            body: [
                { type: 'TextBlock', size: 'Large', weight: 'Bolder', text: title, color: type === 'offline' ? 'Attention' : 'Good' },
                { type: 'TextBlock', text: lines.join('\n'), wrap: true }
            ]
        }
    }]
};
return msg;
